const body = $input.all()[0].json.body;

const raison_visite = body.message?.toolCalls?.[0]?.function?.arguments?.raison_visite || "";
const jour_souhaite = body.message?.toolCalls?.[0]?.function?.arguments?.jour_souhaite || "";
const moment_souhaite = body.message?.toolCalls?.[0]?.function?.arguments?.moment_souhaite || "";
const toolCallId = body.message?.toolCalls?.[0]?.id || "";

return [{
 json: {
 raison_visite,
 jour_souhaite,
 moment_souhaite,
 toolCallId
 }
}];

const events = $input.all().map(e => e.json);
const jourSouhaite = $('Code in JavaScript').first().json.jour_souhaite || "";
const momentSouhaite = $('Code in JavaScript').first().json.moment_souhaite || "";
const toolCallId = $('Code in JavaScript').first().json.toolCallId || "";

const joursFR = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const moisFR = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];

const lower = jourSouhaite.toLowerCase().trim();

// Parser une date spécifique ("26 mai", "1er juin")
function parseDateSpecifique(texte) {
 const t = texte.replace('1er', '1');
 const match = t.match(/(\d{1,2})\s+(janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre)(?:\s+(\d{4}))?/);
 if (match) {
 const jour = parseInt(match[1]);
 const mois = moisFR.indexOf(match[2]);
 const annee = match[3] ? parseInt(match[3]) : new Date().getFullYear();
 return new Date(annee, mois, jour);
 }
 return null;
}

const dateSpecifique = parseDateSpecifique(lower);
let jourDebut = 1;
let jourFin = 180;

if (dateSpecifique) {
 const now = new Date();
 const diff = Math.floor((dateSpecifique - now) / (1000 * 60 * 60 * 24));
 jourDebut = Math.max(1, diff - 1);
 jourFin = diff + 14;
}

const jourSemaineDemande = joursFR.findIndex(j => lower.includes(j));

const disponibilites = [];

for (let d = jourDebut; d < jourFin; d++) {
 const date = new Date();
 date.setDate(date.getDate() + d);
 const jourNom = joursFR[date.getDay()];
 const jourNum = date.getDay();

 if (jourNum === 0 || jourNum === 6) continue;
 if (jourSemaineDemande > 0 && jourNum !== jourSemaineDemande) continue;

 const dateStr = date.toISOString().split('T')[0];

 // Trouver les RDV existants pour ce jour
 const rdvDuJour = events.filter(ev => {
 if (!ev.start) return false;
 const evDate = (ev.start.dateTime || ev.start.date || "").split('T')[0];
 return evDate === dateStr;
 }).map(ev => ({
 debut: new Date(ev.start.dateTime || ev.start.date),
 fin: new Date(ev.end.dateTime || ev.end.date)
 })).sort((a, b) => a.debut - b.debut);

 // Calculer les plages libres entre 8h et 17h
 const ouverture = new Date(`${dateStr}T08:00:00`);
 const fermeture = new Date(`${dateStr}T17:00:00`);
 const plagesLibres = [];
 let cursor = ouverture;

 for (const rdv of rdvDuJour) {
 if (rdv.debut > cursor) {
 const dureeMin = (rdv.debut - cursor) / 60000;
 if (dureeMin >= 60) {
 plagesLibres.push({
 de: `${String(cursor.getHours()).padStart(2,'0')}h${String(cursor.getMinutes()).padStart(2,'0')}`,
 a: `${String(rdv.debut.getHours()).padStart(2,'0')}h${String(rdv.debut.getMinutes()).padStart(2,'0')}`
 });
 }
 }
 if (rdv.fin > cursor) cursor = rdv.fin;
 }

 if (cursor < fermeture) {
 const dureeMin = (fermeture - cursor) / 60000;
 if (dureeMin >= 60) {
 plagesLibres.push({
 de: `${String(cursor.getHours()).padStart(2,'0')}h${String(cursor.getMinutes()).padStart(2,'0')}`,
 a: `${String(fermeture.getHours()).padStart(2,'0')}h${String(fermeture.getMinutes()).padStart(2,'0')}`
 });
 }
 }

 // Filtrer par moment souhaité
 const momentLower = momentSouhaite.toLowerCase();
 let plagesFiltrees = plagesLibres;
 if (momentLower.includes('matin')) {
 plagesFiltrees = plagesLibres.filter(p => parseInt(p.de) < 12);
 } else if (momentLower.includes('après-midi') || momentLower.includes('apres-midi') || momentLower.includes('pm')) {
 plagesFiltrees = plagesLibres.filter(p => parseInt(p.a) > 12);
 }

 if (plagesFiltrees.length > 0) {
 const plagesTexte = plagesFiltrees.map(p => `de ${p.de} à ${p.a}`).join(' et ');
 disponibilites.push({
 jour: `${jourNom} le ${date.getDate()} ${moisFR[date.getMonth()]}`,
 plages: plagesTexte,
 date_iso: dateStr
 });
 }

 if (disponibilites.length >= 5) break;
}

let message = "";
if (disponibilites.length === 0) {
 message = "Aucune disponibilité pour le moment demandé. Voulez-vous essayer un autre jour ou moment ?";
} else {
 message = "Voici les disponibilités : " + disponibilites.map(d => `${d.jour} : ${d.plages}`).join(' | ') + ". Quel jour et quelle heure vous conviennent ? Vous pouvez choisir n'importe quelle heure dans ces plages.";
}

return [{
 json: {
 disponibilites,
 message,
 toolCallId
 }
}];
